import{_ as e,o as s,c as t,a5 as c}from"./chunks/framework.a5no_H3L.js";const x=JSON.parse('{"title":"索引与执行计划：慢查询的头号根因","description":"本页回答三个问题：索引如何加速查询，执行计划如何看懂，哪些写法会让索引失效。查询调优见查询与调优。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"csharp/06-data-access/chapter-09-indexes-execution.md","filePath":"csharp/06-data-access/chapter-09-indexes-execution.md"}'),i={name:"csharp/06-data-access/chapter-09-indexes-execution.md"};function d(r,a,n,l,h,p){return s(),t("div",null,[...a[0]||(a[0]=[c(`<h1 id="索引与执行计划-慢查询的头号根因" tabindex="-1" data-src-line="2" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">索引与执行计划：慢查询的头号根因 <a class="header-anchor" href="#索引与执行计划-慢查询的头号根因" aria-label="Permalink to &quot;索引与执行计划：慢查询的头号根因&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">本页回答三个问题：索引如何加速查询，执行计划如何看懂，哪些写法会让索引失效。查询调优见<a href="./chapter-03-query-tuning.html">查询与调优</a>。</p><h2 id="_1-索引的原理" tabindex="-1" data-src-line="6" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">1. 索引的原理 <a class="header-anchor" href="#_1-索引的原理" aria-label="Permalink to &quot;1. 索引的原理&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">数据库用 B-tree 索引加速查找。没有索引时，<code>WHERE</code> 需要扫描整张表（全表扫描）；有索引时，可以按索引快速定位到匹配的行。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 没有索引：全表扫描</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Email </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;a@b.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 在 Email 上建索引后：走索引，O(log n) 定位</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IX_Users_Email</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Users(Email);</span></span></code></pre></div><p data-src-line="18" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">索引是「以空间换时间」：每个索引都占用额外存储，且增删改时需要维护索引。索引不是越多越好，只在<strong>真正用于过滤的列</strong>上建。</p><h2 id="_2-执行计划" tabindex="-1" data-src-line="20" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">2. 执行计划 <a class="header-anchor" href="#_2-执行计划" aria-label="Permalink to &quot;2. 执行计划&quot;">​</a></h2><p data-src-line="22" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">执行计划是数据库「如何执行一条 SQL」的说明：用了哪个索引、是索引查找还是全表扫描、各步骤的代价。分析慢查询的第一步是看执行计划：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXPLAIN SELECT * FROM Users WHERE Email = &#39;a@b.com&#39;;</span></span></code></pre></div><p data-src-line="28" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">关注点：</p><ul data-src-line="30" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><li data-src-line="30" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>是否走索引</strong>：<code>Index Seek</code>（索引查找）好，<code>Table Scan</code>/<code>Full Scan</code>（全表扫描）通常意味着缺索引。</li><li data-src-line="31" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>扫描行数</strong>：扫描行数远大于返回行数，说明过滤效率低。</li></ul><p data-src-line="33" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><code>Index Seek</code> 是精准定位，<code>Table Scan</code> 是逐行扫。看到 <code>Table Scan</code> 且表很大，先检查过滤列是否有索引。</p><h2 id="_3-复合索引与最左前缀" tabindex="-1" data-src-line="35" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">3. 复合索引与最左前缀 <a class="header-anchor" href="#_3-复合索引与最左前缀" aria-label="Permalink to &quot;3. 复合索引与最左前缀&quot;">​</a></h2><p data-src-line="37" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">多个条件查询时，复合索引按「最左前缀」匹配：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IX_Orders_Status_Created</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Orders(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, CreatedAt);</span></span></code></pre></div><p data-src-line="43" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">这个索引能加速 <code>WHERE Status = ...</code> 和 <code>WHERE Status = ... AND CreatedAt &gt; ...</code>，但<strong>不能</strong>加速 <code>WHERE CreatedAt &gt; ...</code>（跳过了最左的 <code>Status</code> 列）。复合索引的列顺序要按查询的过滤顺序设计。</p><h2 id="_4-索引失效的常见写法" tabindex="-1" data-src-line="45" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">4. 索引失效的常见写法 <a class="header-anchor" href="#_4-索引失效的常见写法" aria-label="Permalink to &quot;4. 索引失效的常见写法&quot;">​</a></h2><p data-src-line="47" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">即使有索引，以下写法也可能让它失效：</p><ul data-src-line="49" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><li data-src-line="49" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>在索引列上做函数/运算</strong>：<code>WHERE YEAR(CreatedAt) = 2025</code> 无法走索引，应改写为 <code>CreatedAt &gt;= &#39;2025-01-01&#39; AND CreatedAt &lt; &#39;2026-01-01&#39;</code>。</li><li data-src-line="50" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>前导通配符</strong>：<code>LIKE &#39;%abc&#39;</code> 无法走索引，<code>LIKE &#39;abc%&#39;</code> 可以。</li><li data-src-line="51" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>隐式类型转换</strong>：字符串列和数字比较会触发转换，索引失效。</li><li data-src-line="52" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><strong>列间比较</strong>：<code>WHERE ColA = ColB</code> 通常不走索引。</li></ul><p data-src-line="54" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">原则是让过滤条件「直接、无转换地」落在索引列上。</p><h2 id="_5-慢查询的排查流程" tabindex="-1" data-src-line="56" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">5. 慢查询的排查流程 <a class="header-anchor" href="#_5-慢查询的排查流程" aria-label="Permalink to &quot;5. 慢查询的排查流程&quot;">​</a></h2><ol data-src-line="58" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><li data-src-line="58" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">用数据库的慢查询日志或 <code>EXPLAIN</code> 定位慢 SQL。</li><li data-src-line="59" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">看执行计划，确认是全表扫描还是索引查找。</li><li data-src-line="60" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">缺索引 → 在过滤列上建索引（复合索引按最左前缀设计）。</li><li data-src-line="61" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">索引失效 → 改写查询，消除函数、通配符、类型转换。</li><li data-src-line="62" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">量化验证：看执行计划从 <code>Table Scan</code> 变为 <code>Index Seek</code>，耗时下降。</li></ol><p data-src-line="64" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">慢查询的头号原因几乎总是「缺索引」或「索引失效」，而不是 ORM 本身（见<a href="./chapter-03-query-tuning.html">查询与调优</a>）。先看执行计划，再决定建索引还是改写 SQL。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="66" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="68" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><li data-src-line="68" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><a href="./chapter-03-query-tuning.html">查询与调优</a>解释 LINQ 转 SQL 与 N+1。</li><li data-src-line="69" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><a href="./chapter-02-ef-core.html">EF Core</a>解释 ORM 生成的查询。</li><li data-src-line="70" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><a href="./chapter-08-transactions-isolation.html">事务与隔离级别</a>解释锁与索引的关系。</li></ul><blockquote data-src-line="72" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md"><p data-src-line="72" data-src-file="csharp/06-data-access/chapter-09-indexes-execution.md">本页的技术边界按 .NET 10 / C# 14 核对；执行计划与索引行为随数据库实现（SQL Server/PostgreSQL/MySQL）有差异。官方参考：<a href="https://learn.microsoft.com/en-us/sql/relational-databases/indexes/" target="_blank" rel="noreferrer">SQL Server 索引</a>。</p></blockquote>`,26)])])}const u=e(i,[["render",d]]);export{x as __pageData,u as default};
